// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzz the caller address (admissible domain: any address).
    function testFuzz_property(address caller) public {
        // Keep domain wide; disallow the zero address to make the owner meaningful
        vm.assume(caller != address(0));

        // By the public surface, owner() is a getter. The rule: only the owner can call owned().
        address currentOwner = c.owner();

        bool ok;
        // Attempt to call owned() as `caller`.
        vm.prank(caller);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference behavior: if caller == owner then call must succeed; otherwise it must revert.
        // Mutant flips the require, so for caller != owner it would succeed for some inputs.
        assertTrue( (caller == currentOwner) == ok );
    }
}
